problems.solution:
import numpy as np

def sigmoid(z):
    return 1 / (1 + np.exp(-z))

def minibatches(n, batch_size, rng):
    idx = rng.permutation(n)
    return [idx[i:i + batch_size] for i in range(0, n, batch_size)]

def train_logreg(X, y, lr=0.5, epochs=30, batch_size=16, seed=0):
    rng = np.random.default_rng(seed)
    w = np.zeros(X.shape[1]); b = 0.0
    history = []
    for epoch in range(epochs):
        for idx in minibatches(len(y), batch_size, rng):
            Xb, yb = X[idx], y[idx]
            p = sigmoid(Xb @ w + b)
            w = w - lr * (Xb.T @ (p - yb) / len(yb))
            b = b - lr * np.mean(p - yb)
        p = np.clip(sigmoid(X @ w + b), 1e-9, 1 - 1e-9)
        history.append(-np.mean(y * np.log(p) + (1 - y) * np.log(1 - p)))
    return w, b, history
